1	{"nl": "show disk usage for every mounted filesystem", "bash": "df -h"}
2	{"nl": "show disk usage in human-readable format sorted by size", "bash": "df -h | sort -k5 -rh"}
3	{"nl": "check how much space the /var directory is using", "bash": "du -sh /var"}
4	{"nl": "find the top 10 largest directories under /home", "bash": "du -h /home | sort -rh | head -10"}
5	{"nl": "find the top 10 largest files on the entire filesystem", "bash": "find / -type f -printf '%s %p\\n' 2>/dev/null | sort -rn | head -10"}
6	{"nl": "show inode usage for all filesystems", "bash": "df -i"}
7	{"nl": "check which filesystem a file belongs to", "bash": "df -h /var/log/syslog"}
8	{"nl": "add 4GB of swap space", "bash": "sudo fallocate -l 4G /swapfile && sudo chmod 600 /swapfile && sudo mkswap /swapfile && sudo swapon /swapfile"}
9	{"nl": "show current swap usage", "bash": "swapon --show"}
10	{"nl": "disable and remove the current swapfile", "bash": "sudo swapoff /swapfile && sudo rm /swapfile"}

1	{"nl": "show total CPU usage per user from ps output", "bash": "ps aux | awk 'NR>1 {cpu[$1]+=$3} END {for (u in cpu) print cpu[u], u}' | sort -rn | head -10"}
2	{"nl": "show total memory usage in MB per user", "bash": "ps aux | awk 'NR>1 {mem[$1]+=$4} END {for (u in mem) printf \"%.1f MB  %s\\n\", mem[u]*16, u}' | sort -rn"}
3	{"nl": "count how many times each HTTP status code appears in the nginx access log", "bash": "awk '{print $9}' /var/log/nginx/access.log | sort | uniq -c | sort -rn"}
4	{"nl": "show the top 10 slowest nginx requests in milliseconds", "bash": "awk '{print $NF, $7}' /var/log/nginx/access.log | sort -rn | head -10"}
5	{"nl": "calculate the average response time from nginx logs", "bash": "awk '{sum+=$NF; n++} END {printf \"avg: %.3f ms\\n\", sum/n}' /var/log/nginx/access.log"}
